# TASK: instalar loop_analista v2 (4 niveles) — backup + compile-check + test + reporte
import base64,hashlib,json,os,py_compile,re,subprocess,sys,time,urllib.request
B="/home/opc/bot_semillas"
V2_B64=""
def scrub(s):
    if not s: return s
    s=re.sub(r"(github_pat_[A-Za-z0-9_]+|gh[posru]_[A-Za-z0-9]+|sk-ant-[A-Za-z0-9_\-]+)","<TOK>",s)
    return re.sub(r"[A-Za-z0-9]{56,}","<REDACTED>",s)
tok=""
try:
    for L in open(B+"/.env"):
        m=re.search(r"(github_pat_[A-Za-z0-9_]+|gh[posru]_[A-Za-z0-9]+)",L)
        if m: tok=m.group(1)
except Exception: pass
info={"task":"install_loop_analista_v2","now":time.strftime("%Y-%m-%d %H:%M:%SZ",time.gmtime()),"pasos":[]}
def step(s): info["pasos"].append(s); print("[v2install]",s)
try:
    src=base64.b64decode(V2_B64)
    info["sha256"]=hashlib.sha256(src).hexdigest()[:16]
    tmp=B+"/loop_analista_v2_tmp.py"
    open(tmp,"wb").write(src)
    py_compile.compile(tmp,doraise=True); step("compile OK (%d bytes)"%len(src))
    tgt=B+"/loop_analista.py"; bak=B+"/loop_analista.py.bak.v1"
    if os.path.exists(tgt) and not os.path.exists(bak):
        open(bak,"wb").write(open(tgt,"rb").read()); step("backup -> loop_analista.py.bak.v1")
    os.replace(tmp,tgt); step("instalado loop_analista.py")
    test=("import sys; sys.path.insert(0,%r); import loop_analista as A;"
          "t,o=A.consolidate(); m=A.rolling_metrics(t); import json;"
          "print(json.dumps({'finales':sum(1 for x in t if x.get('final')),"
          "'abiertas':sorted(o.keys()),'ganesha_hist':m['ganesha']['historico'],"
          "'semillas_hist':m['semillas']['historico']}))")%B
    r=subprocess.run([B+"/venv/bin/python","-c",test],capture_output=True,text=True,timeout=120,cwd=B)
    info["test_stdout"]=scrub(r.stdout[-1500:]); info["test_stderr"]=scrub(r.stderr[-800:])
    step("test rc=%d"%r.returncode)
    info["ok"]=(r.returncode==0)
except Exception as e:
    info["ok"]=False; info["error"]=scrub(str(e)[:300])
U="https://api.github.com/repos/calcagnoagustin/radar/contents/docs/_diag.json"
def R(m,d=None):
    q=urllib.request.Request(U,data=d,method=m); q.add_header("Authorization","token "+tok); q.add_header("User-Agent","v2install")
    return urllib.request.urlopen(q,timeout=30).read()
sha=None
try: sha=json.loads(R("GET")).get("sha")
except Exception: pass
p={"message":"install loop_analista v2","content":base64.b64encode(json.dumps(info,indent=1).encode()).decode()}
if sha: p["sha"]=sha
try: R("PUT",json.dumps(p).encode()); print("REPORTADO ok=%s"%info.get("ok"))
except Exception as e: print("PUSH_ERR",e)
